        "html": "<div style=\"display:flex;gap:28px;align-items:flex-end;flex-wrap:wrap;justify-content:center\">\n  {{sym:22043FBC-A47D-4828-9FBB-AC9604F021DD}}\n  {{sym:F1BBEC31-4D16-4BB3-892C-7257C2A43601}}\n  {{sym:E4A9B4B0-3C9F-4436-9C9E-5DED2F2CBA6F}}\n  {{sym:65D3A449-8572-4EBF-9F05-78B63C752374}}\n  {{sym:1EA5654D-C993-4442-85A6-63FCFCE972B0}}\n  {{sym:82A88842-3175-4C7A-8FC7-A0DF3927F930}}\n  {{sym:BD8D64A1-20DD-43DA-85C4-74256CB57AF4}}\n</div>"
